<?php
use PreConselho\Support\Csrf;
$content=$content??'';
$user=$_SESSION['user']??null;
$path=parse_url($_SERVER['REQUEST_URI']??'/',PHP_URL_PATH)?:'/';
$isLogin=$path==='/login'&&!$user;
$isPortal=$path==='/';
$isApc=str_starts_with($path,'/apc');
$isCouncil=!$isPortal&&!$isApc&&!$isLogin;
$roleLabels=['ADMIN'=>'Administrador','COORDENADOR'=>'Coordenação','PROFESSOR'=>'Professor'];
$isActive=static fn(string $route):string=>($route==='/'?$path==='/':str_starts_with($path,$route))?' active':'';
$brandTitle=$isPortal?'Gestão Pedagógica':($isApc?'APCs':'Conselho de Classe');
$brandSubtitle=$isPortal?'Sistemas da escola':($isApc?'Atividades Pedagógicas Complementares':'Documentos pedagógicos');
$brandMark=$isPortal?'GP':($isApc?'APC':'CC');
$assetVersion=static function(string $file):string{$path=dirname(__DIR__,2).'/public/assets/'.$file;$modified=is_file($path)?filemtime($path):false;return $modified===false?'1':(string)$modified;};
?><!doctype html>
<html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#173f5f"><title><?=e($title??$brandTitle)?> · Gestão Pedagógica</title><link rel="stylesheet" href="/assets/app.css?v=<?=e($assetVersion('app.css'))?>"></head>
<body class="<?=trim(($isLogin?'login-page ':'').($isApc?'apc-page ':''))?>"><a class="skip" href="#conteudo">Pular para o conteúdo</a>
<header class="app-header"><div class="header-inner"><a class="brand" href="/" aria-label="Ir para o início"><span class="brand-mark" aria-hidden="true"><?=e($brandMark)?></span><span><strong><?=e($brandTitle)?></strong><small><?=e($brandSubtitle)?></small></span></a>
<?php if($user):?><button class="menu-toggle" type="button" aria-expanded="false" aria-controls="main-nav"><span aria-hidden="true">☰</span> Menu</button><nav id="main-nav" aria-label="Principal"><a class="<?=$isActive('/')?>" href="/"><span aria-hidden="true">⌂</span> Início</a><a class="<?=$isCouncil?' active':''?>" href="/conselho">Conselho</a><a class="<?=$isApc?' active':''?>" href="/apc">APCs</a><?php if($isApc&&$user['perfil']!=='PROFESSOR'):?><a class="<?=$isActive('/apc/relatorios')?>" href="/apc/relatorios"><span aria-hidden="true">▤</span> Relatórios APC</a><?php elseif(!$isApc&&$user['perfil']!=='PROFESSOR'):?><a class="<?=$isActive('/consolidados')?>" href="/consolidados"><span aria-hidden="true">▤</span> Consolidado</a><?php endif;?><?php if($isApc&&$user['perfil']==='ADMIN'):?><a class="<?=$isActive('/apc/admin')?>" href="/apc/admin"><span aria-hidden="true">⚙</span> Admin APC</a><?php elseif(!$isApc&&$user['perfil']==='ADMIN'):?><a class="<?=$isActive('/admin')?>" href="/admin"><span aria-hidden="true">⚙</span> Administração</a><?php endif;?></nav><div class="user-area"><span class="user-copy"><strong><?=e($user['nome'])?></strong><small><?=e($roleLabels[$user['perfil']]??$user['perfil'])?></small></span><form method="post" action="/logout"><input type="hidden" name="_csrf" value="<?=e(Csrf::token())?>"><button class="button ghost" title="Encerrar sessão">Sair</button></form></div><?php endif;?></div></header>
<main id="conteudo"><?php if(!empty($_SESSION['flash'])):?><div class="flash" role="status"><span aria-hidden="true">✓</span><span><?=e($_SESSION['flash']);unset($_SESSION['flash']);?></span></div><?php endif;?><?=$content?><?php if(isset($report)&&($user['perfil']??'')==='ADMIN'&&$report['status']==='APROVADO'&&$report['periodo_status']!=='ENCERRADO'):?><section class="card danger-zone"><div><p class="eyebrow">Ação administrativa</p><h2>Reabrir relatório aprovado</h2><p>O relatório voltará ao professor para ajustes e a ação ficará registrada no histórico.</p></div><form method="post" action="/admin/relatorios/<?=e($report['id'])?>/reabrir"><input type="hidden" name="_csrf" value="<?=e(Csrf::token())?>"><label>Motivo da reabertura <textarea name="justificativa" required maxlength="2000" placeholder="Explique por que o relatório precisa ser alterado"></textarea></label><button class="danger" data-confirm="Confirma a reabertura deste relatório?">Reabrir relatório</button></form></section><?php endif;?></main><?php if(!$isLogin):?><footer><?=e($brandTitle)?> <span>•</span> Gestão pedagógica da escola</footer><?php endif;?><script src="/assets/app.js?v=<?=e($assetVersion('app.js'))?>" defer></script><?php if(is_file(dirname(__DIR__,2).'/public/assets/collaboration.js')):?><script src="/assets/collaboration.js?v=<?=e($assetVersion('collaboration.js'))?>" defer></script><?php endif;?></body></html>
